    aplicar: cada(`${linea}/cac:Status/cbc:ConditionCode`, quitar),
  },
  {
    nombre: 'condición fuera del catálogo 19',
    tipos: ['RC'],
    aplicar: cada(`${linea}/cac:Status/cbc:ConditionCode`, texto('9')),
  },
  {
    nombre: 'serie-número de factura en resumen',
