  },
  {
    nombre: 'pago con monto 0',
    tipos: ['RC'],
    aplicar: cada(`${linea}/*[local-name()='BillingPayment']/cbc:PaidAmount`, texto('0.00')),
  },
  {
    nombre: 'pago sin tipo',
    tipos: ['RC'],
    aplicar: cada(`${linea}/*[local-name()='BillingPayment']/cbc:InstructionID`, quitar),
  },
  {
